let num_peli=0;

document.getElementById('agregar-pelicula').addEventListener('click', ()=>{

    const obtenerColorHexAleatorio = () =>
        `#${Math.floor(Math.random() * 0xFFFFFF)
            .toString(16)
            .padStart(6, "0")}`;

    if (num_peli<5){
        document.getElementById('contenedor').innerHTML +=
            '<div class="card m-3 " style="width: 15rem; background-color: '+obtenerColorHexAleatorio()+'">' +
            '<img src="' + peliculas[num_peli].imagen + '" class="card-img-top" >' +
            '<div class="card-body" >' +
            peliculas[num_peli].titulo
            + peliculas[num_peli].descripcion +
            '<p>Calificacion: ' + peliculas[num_peli].calificacion +
            '</div>' +
            '</div>';
        num_peli++;
    }
});